import { db } from "../queries/connection";
import { sql } from "drizzle-orm";

export interface RetentionPolicy {
  tableName: string;
  class: "E" | "G" | "D";
  retainDays: number;
  dateColumn: string;
  whereClause?: string;
  rollupBefore?: () => Promise<void>;
  customCleanup?: (dryRun: boolean) => Promise<number>;
  description: string;
}

export interface TablePruneResult {
  table: string;
  class: string;
  prunedCount: number;
  durationMs: number;
  dryRun: boolean;
  rolledUp?: boolean;
}

export interface DataRetentionJobResult {
  dryRun: boolean;
  totalPruned: number;
  results: TablePruneResult[];
  durationMs: number;
}

/**
 * Pre-deletion rollup: Aggregate AI token ledgers into ai_cost_monthly before purging raw rows.
 * Idempotent: Marks processed rows inside an ACID transaction so retries or failed deletes do not double accumulated values.
 */
async function rollupAiTokensBeforePrune(cutoffDateStr: string): Promise<void> {
  await db.transaction(async (tx) => {
    await tx.execute(sql`
      INSERT INTO ai_cost_monthly (
        user_id,
        user_type,
        billing_period,
        provider_slug,
        model_id,
        total_tokens,
        prompt_tokens,
        completion_tokens,
        cost_usd,
        cost_egp,
        call_count
      )
      SELECT
        user_id,
        user_type,
        billing_period,
        provider_slug,
        model_id,
        COALESCE(SUM(total_tokens), 0) AS total_tokens,
        COALESCE(SUM(prompt_tokens), 0) AS prompt_tokens,
        COALESCE(SUM(completion_tokens), 0) AS completion_tokens,
        COALESCE(SUM(cost_usd), 0.00000000) AS cost_usd,
        COALESCE(SUM(cost_egp), 0.000000) AS cost_egp,
        COUNT(*) AS call_count
      FROM ai_token_ledgers
      WHERE created_at < ${cutoffDateStr}
        AND (metadata IS NULL OR JSON_UNQUOTE(JSON_EXTRACT(metadata, '$.rolled_up')) IS NULL OR JSON_UNQUOTE(JSON_EXTRACT(metadata, '$.rolled_up')) != 'true')
      GROUP BY user_id, user_type, billing_period, provider_slug, model_id
      ON DUPLICATE KEY UPDATE
        total_tokens = total_tokens + VALUES(total_tokens),
        prompt_tokens = prompt_tokens + VALUES(prompt_tokens),
        completion_tokens = completion_tokens + VALUES(completion_tokens),
        cost_usd = cost_usd + VALUES(cost_usd),
        cost_egp = cost_egp + VALUES(cost_egp),
        call_count = call_count + VALUES(call_count)
    `);

    await tx.execute(sql`
      UPDATE ai_token_ledgers
      SET metadata = JSON_SET(COALESCE(metadata, JSON_OBJECT()), '$.rolled_up', 'true')
      WHERE created_at < ${cutoffDateStr}
        AND (metadata IS NULL OR JSON_UNQUOTE(JSON_EXTRACT(metadata, '$.rolled_up')) IS NULL OR JSON_UNQUOTE(JSON_EXTRACT(metadata, '$.rolled_up')) != 'true')
    `);
  });
}

/**
 * Pre-deletion rollup: Aggregate ad clicks into ad_stats_daily before purging.
 * Idempotent: Uses GREATEST so retries or failed deletes do not double accumulated values.
 */
async function rollupAdClicksBeforePrune(cutoffDateStr: string): Promise<void> {
  await db.execute(sql`
    INSERT INTO ad_stats_daily (
      ad_id,
      day,
      clicks,
      impressions
    )
    SELECT
      ad_id,
      DATE(created_at) AS day,
      COUNT(*) AS clicks,
      0 AS impressions
    FROM ad_clicks
    WHERE created_at < ${cutoffDateStr}
    GROUP BY ad_id, DATE(created_at)
    ON DUPLICATE KEY UPDATE
      clicks = GREATEST(ad_stats_daily.clicks, VALUES(clicks))
  `);
}

/**
 * Declarative Retention Policies for Ephemeral and Telemetry Tables (§3.7 / Phase 4)
 */
export const RETENTION_POLICIES: RetentionPolicy[] = [
  {
    tableName: "classification_logs",
    class: "E",
    retainDays: 90,
    dateColumn: "created_at",
    description: "Classification telemetry logs. Heavy JSON traces nullified after 30 days.",
    customCleanup: async (dryRun: boolean) => {
      // Lighten 30-day old logs by nulling out heavy reasoning trace & ai_result
      const cutoff30 = new Date(Date.now() - 30 * 24 * 3600 * 1000).toISOString();
      if (!dryRun) {
        await db.execute(sql`
          UPDATE classification_logs
          SET reasoning_trace_light = NULL, ai_result = NULL
          WHERE created_at < ${cutoff30}
            AND (reasoning_trace_light IS NOT NULL OR ai_result IS NOT NULL)
          LIMIT 5000
        `);
      }
      return 0;
    },
  },
  {
    tableName: "ai_token_ledgers",
    class: "E",
    retainDays: 90,
    dateColumn: "created_at",
    description: "Raw AI token ledger rows. Rolled up into ai_cost_monthly before deletion.",
    rollupBefore: async () => {
      const cutoff90 = new Date(Date.now() - 90 * 24 * 3600 * 1000)
        .toISOString()
        .slice(0, 19)
        .replace("T", " ");
      await rollupAiTokensBeforePrune(cutoff90);
    },
  },
  {
    tableName: "user_analytics",
    class: "E",
    retainDays: 30,
    dateColumn: "created_at",
    description: "Pure product telemetry events.",
  },
  {
    tableName: "notification_logs",
    class: "E",
    retainDays: 90,
    dateColumn: "sent_at",
    description: "Notification dispatch history for rate-limit and deduplication.",
  },
  {
    tableName: "ad_clicks",
    class: "E",
    retainDays: 90,
    dateColumn: "created_at",
    description: "Ad click events. Rolled up into ad_stats_daily before deletion.",
    rollupBefore: async () => {
      const cutoff90 = new Date(Date.now() - 90 * 24 * 3600 * 1000)
        .toISOString()
        .slice(0, 19)
        .replace("T", " ");
      await rollupAdClicksBeforePrune(cutoff90);
    },
  },
  {
    tableName: "api_key_errors",
    class: "E",
    retainDays: 30,
    dateColumn: "created_at",
    whereClause: "resolved = 1",
    description: "Resolved API key error alerts.",
  },
  {
    tableName: "api_key_errors",
    class: "E",
    retainDays: 90,
    dateColumn: "created_at",
    whereClause: "resolved = 0",
    description: "Unresolved API key errors.",
  },
  {
    tableName: "profile_learning_events",
    class: "E",
    retainDays: 180,
    dateColumn: "created_at",
    description: "AI persona evolution and learning audit events.",
  },
  {
    tableName: "voice_usage",
    class: "E",
    retainDays: 90,
    dateColumn: "created_at",
    description: "Raw voice call duration records.",
  },
  {
    tableName: "ai_action_audit_logs",
    class: "E",
    retainDays: 365,
    dateColumn: "created_at",
    description: "Financial action audit trail (1-year mandatory compliance).",
  },
  {
    tableName: "chat_messages",
    class: "G",
    retainDays: 90,
    dateColumn: "created_at",
    whereClause: "conversation_id IN (SELECT conversation_id FROM ai_conversation_summaries)",
    description: "Chat messages older than 90 days with existing conversation summaries.",
  },
  {
    tableName: "pending_clarifications",
    class: "D",
    retainDays: 30,
    dateColumn: "created_at",
    whereClause: "status != 'pending'",
    description: "Resolved or dismissed clarification prompts.",
  },
  {
    tableName: "ai_pending_actions",
    class: "D",
    retainDays: 30,
    dateColumn: "expires_at",
    description: "Expired unconfirmed actions.",
  },
  {
    tableName: "auth_challenges",
    class: "D",
    retainDays: 7,
    dateColumn: "expires_at",
    description: "Expired WebAuthn/passkey challenges.",
  },
];

/**
 * Executes a chunked bounded delete loop (LIMIT 5000) with a sleep between chunks.
 */
async function chunkedDelete(
  tableName: string,
  whereCondition: string,
  chunkSize = 5000,
  pauseMs = 50,
): Promise<number> {
  let totalDeleted = 0;

  while (true) {
    const rawSql = `DELETE FROM \`${tableName}\` WHERE ${whereCondition} LIMIT ${chunkSize}`;
    const [result] = (await db.execute(sql.raw(rawSql))) as unknown as [{ affectedRows?: number }];
    const affected = Number(result?.affectedRows ?? 0);
    totalDeleted += affected;

    if (affected < chunkSize) {
      break;
    }

    if (pauseMs > 0) {
      await new Promise((resolve) => setTimeout(resolve, pauseMs));
    }
  }

  return totalDeleted;
}

/**
 * Counts rows matching a retention policy for dry-run reports.
 */
async function countMatchingRows(
  tableName: string,
  whereCondition: string,
): Promise<number> {
  const rawSql = `SELECT COUNT(*) AS count FROM \`${tableName}\` WHERE ${whereCondition}`;
  const [rows] = (await db.execute(sql.raw(rawSql))) as unknown as [[{ count: number | string }]];
  const row = rows?.[0];
  return Number(row?.count ?? 0);
}

/**
 * Runs the data retention lifecycle job (§3.7 / §3.8).
 * Supports dry-run mode, pre-deletion rollups, chunked deletion, and detailed logging.
 */
export async function runDataRetentionJob(options: {
  dryRun?: boolean;
} = {}): Promise<DataRetentionJobResult> {
  const dryRun = Boolean(options.dryRun);
  const startTime = performance.now();
  const results: TablePruneResult[] = [];
  let totalPruned = 0;

  console.log(`[DataRetentionJob] Starting data retention run (dryRun: ${dryRun})...`);

  for (const policy of RETENTION_POLICIES) {
    const policyStart = performance.now();
    let prunedCount = 0;
    let rolledUp = false;

    try {
      const cutoffDate = new Date(Date.now() - policy.retainDays * 24 * 3600 * 1000);
      const cutoffStr = cutoffDate.toISOString().slice(0, 19).replace("T", " ");

      let condition = `\`${policy.dateColumn}\` < '${cutoffStr}'`;
      if (policy.whereClause) {
        condition += ` AND (${policy.whereClause})`;
      }

      // 1. Run custom pre-cleanup if defined (e.g. JSON trace nullification)
      if (policy.customCleanup) {
        await policy.customCleanup(dryRun);
      }

      // 2. Perform rollup before deletion if required
      if (policy.rollupBefore && !dryRun) {
        await policy.rollupBefore();
        rolledUp = true;
      }

      // 3. Either count (dryRun) or chunk-delete
      if (dryRun) {
        prunedCount = await countMatchingRows(policy.tableName, condition);
      } else {
        prunedCount = await chunkedDelete(policy.tableName, condition, 5000, 50);
      }

      totalPruned += prunedCount;
      const durationMs = Math.round(performance.now() - policyStart);

      results.push({
        table: policy.tableName,
        class: policy.class,
        prunedCount,
        durationMs,
        dryRun,
        rolledUp,
      });

      console.log(
        `[DataRetentionJob] ${policy.tableName} (${policy.class}): ${dryRun ? "found" : "pruned"} ${prunedCount} rows in ${durationMs}ms`,
      );
    } catch (err: any) {
      console.error(
        `[DataRetentionJob] Error processing retention policy for ${policy.tableName}:`,
        err.message || err,
      );
    }
  }

  const durationMs = Math.round(performance.now() - startTime);
  console.log(
    `[DataRetentionJob] Completed. Total rows ${dryRun ? "eligible" : "pruned"}: ${totalPruned} across ${results.length} policies in ${durationMs}ms.`,
  );

  return {
    dryRun,
    totalPruned,
    results,
    durationMs,
  };
}

/**
 * Pro receipt / screenshot parsing — OCR heuristics first, Gemini vision fallback.
 */
import { GoogleGenerativeAI, SchemaType } from "@google/generative-ai";
import { mapModelName } from "./model-mapper";
import { normalizeText } from "./text-normalizer";
import { extractAmounts } from "./entity-extractor";
import { runSmartPipeline, type PipelineResult } from "./smart-pipeline";
import type { PlanId } from "./ai-usage-policy";

const receiptSchema = {
  type: SchemaType.OBJECT,
  properties: {
    amount: { type: SchemaType.NUMBER },
    description: { type: SchemaType.STRING },
    main_category: { type: SchemaType.STRING },
    sub_category: { type: SchemaType.STRING },
    merchant: { type: SchemaType.STRING, nullable: true },
    transaction_type: { type: SchemaType.STRING },
    confidence: { type: SchemaType.NUMBER },
    ocr_text: { type: SchemaType.STRING, nullable: true },
  },
  required: [
    "amount",
    "description",
    "main_category",
    "sub_category",
    "transaction_type",
    "confidence",
  ],
} as any;

export interface ReceiptParseResult {
  amount: number;
  description: string;
  category: string;
  subCategory: string;
  type: "income" | "expense";
  confidence: number;
  merchant?: string;
  ocrText?: string;
  tokensUsed: number;
  parsedBy: string;
  pipeline?: PipelineResult;
}

const MAX_IMAGE_BASE64_CHARS = 4_500_000;

export function stripDataUri(base64: string): string {
  return base64.includes(",") ? base64.split(",")[1]! : base64;
}

/** Downscale payload by truncating oversized base64 (client should compress; this is a safety net). */
export function guardImagePayloadSize(base64: string): string {
  const pure = stripDataUri(base64);
  if (pure.length <= MAX_IMAGE_BASE64_CHARS) return pure;
  return pure.slice(0, MAX_IMAGE_BASE64_CHARS);
}

/** Regex OCR for Egyptian bank SMS / receipt screenshots */
export function extractFromImageText(
  raw: string,
): Partial<ReceiptParseResult> | null {
  const text = normalizeText(raw);
  const amounts = extractAmounts(text);
  if (!amounts.length) return null;

  const amount = amounts[0].amount;
  let type: "income" | "expense" = "expense";
  if (/تم إيداع|ايداع|استلمت|received|credit/i.test(text)) type = "income";
  if (/تم خصم|خصم|سحب|debit|paid/i.test(text)) type = "expense";

  let description = "عملية من صورة";
  const merchantMatch = text.match(
    /(?:من|at|@)\s*([A-Za-z\u0600-\u06FF0-9\s]{3,40})/,
  );
  if (merchantMatch) description = merchantMatch[1].trim().slice(0, 80);

  return {
    amount,
    description,
    type,
    confidence: 72,
    ocrText: text.slice(0, 500),
  };
}

export async function parseReceiptWithVision(
  imageBase64: string,
  mimeType: string,
  apiKey: string,
  modelName: string,
  maxTokens: number,
): Promise<{ parsed: ReceiptParseResult | null; tokensUsed: number }> {
  const pure = guardImagePayloadSize(imageBase64);
  const genAI = new GoogleGenerativeAI(apiKey);
  const model = genAI.getGenerativeModel({
    model: mapModelName(modelName || "gemini-2.5-flash"),
    systemInstruction: `استخرج عملية مالية واحدة من صورة إيصال/سكرين شوت بنك أو فاتورة مصرية.
أعد JSON: amount, description, main_category, sub_category, merchant, transaction_type (expense|income), confidence, ocr_text.
استخدم الفئات العربية المعتادة في SpinSmart.`,
    generationConfig: {
      temperature: 0.1,
      maxOutputTokens: maxTokens,
      responseMimeType: "application/json",
      responseSchema: receiptSchema,
    },
  });

  const result = await model.generateContent([
    { text: "استخرج العملية المالية من الصورة:" },
    { inlineData: { mimeType: mimeType.split(";")[0], data: pure } },
  ]);

  const raw = result.response.text();
  const tokensUsed = result.response.usageMetadata?.totalTokenCount || 0;
  let data: any;
  try {
    data = JSON.parse(
      raw
        .replace(/```json?/g, "")
        .replace(/```/g, "")
        .trim(),
    );
  } catch {
    const m = raw.match(/\{[\s\S]*\}/);
    if (!m) return { parsed: null, tokensUsed };
    data = JSON.parse(m[0]);
  }

  return {
    parsed: {
      amount: Number(data.amount) || 0,
      description: data.description || "من صورة",
      category: data.main_category || "متنوعات",
      subCategory: data.sub_category || "عام",
      type: data.transaction_type === "income" ? "income" : "expense",
      confidence: Number(data.confidence) || 75,
      merchant: data.merchant,
      ocrText: data.ocr_text,
      tokensUsed,
      parsedBy: "vision",
    },
    tokensUsed,
  };
}

export async function parseReceiptImage(input: {
  imageBase64: string;
  mimeType: string;
  apiKey: string;
  apiKey2: string;
  modelName: string;
  maxTokens: number;
  userId: number;
  userType: string;
  userPlan: PlanId;
  userDict: Array<{ word: string; category: string; subCategory?: string }>;
  monthlyContext: { totalIncome: number; totalExpense: number };
  profileSummary?: string;
  ocrTextHint?: string;
}): Promise<ReceiptParseResult | null> {
  let tokensUsed = 0;

  if (input.ocrTextHint && input.ocrTextHint.length >= 8) {
    const heuristic = extractFromImageText(input.ocrTextHint);
    if (heuristic?.amount && heuristic.amount > 0) {
      const pipeline = await runSmartPipeline({
        text: `${heuristic.description} ${heuristic.amount} جنيه`,
        userId: input.userId,
        userType: input.userType,
        userPlan: input.userPlan,
        userDict: input.userDict,
        apiKey: input.apiKey,
        apiKey2: input.apiKey2,
        modelName: input.modelName,
        maxTokens: Math.min(input.maxTokens, 1024),
        monthlyContext: input.monthlyContext,
        userProfileContext: { promptSummary: input.profileSummary },
        skipClarification: true,
      });
      const item = pipeline.items[0];
      if (item) {
        return {
          amount: item.amount || heuristic.amount,
          description: item.description || heuristic.description!,
          category: item.category,
          subCategory: item.subCategory,
          type: item.type as "income" | "expense",
          confidence: Math.max(item.confidence, heuristic.confidence || 70),
          ocrText: heuristic.ocrText,
          tokensUsed: pipeline.tokensUsed,
          parsedBy: pipeline.parsedBy,
          pipeline,
        };
      }
    }
  }

  const vision = await parseReceiptWithVision(
    input.imageBase64,
    input.mimeType,
    input.apiKey,
    input.modelName,
    input.maxTokens,
  );
  tokensUsed += vision.tokensUsed;
  if (!vision.parsed || vision.parsed.amount <= 0) return null;

  const textForPipeline =
    vision.parsed.ocrText ||
    `${vision.parsed.description} ${vision.parsed.amount} جنيه`;

  const pipeline = await runSmartPipeline({
    text: textForPipeline,
    userId: input.userId,
    userType: input.userType,
    userPlan: input.userPlan,
    userDict: input.userDict,
    apiKey: input.apiKey,
    apiKey2: input.apiKey2,
    modelName: input.modelName,
    maxTokens: Math.min(input.maxTokens, 1536),
    monthlyContext: input.monthlyContext,
    userProfileContext: { promptSummary: input.profileSummary },
    skipClarification: true,
  });

  tokensUsed += pipeline.tokensUsed;
  const item = pipeline.items[0] || {
    amount: vision.parsed.amount,
    category: vision.parsed.category,
    subCategory: vision.parsed.subCategory,
    description: vision.parsed.description,
    type: vision.parsed.type,
    confidence: vision.parsed.confidence,
  };

  return {
    amount: item.amount,
    description: item.description,
    category: item.category,
    subCategory: item.subCategory,
    type: item.type as "income" | "expense",
    confidence: Math.max(item.confidence, vision.parsed.confidence),
    merchant: vision.parsed.merchant,
    ocrText: vision.parsed.ocrText,
    tokensUsed,
    parsedBy: `image:${pipeline.parsedBy}`,
    pipeline,
  };
}

import { and, eq, inArray, or } from "drizzle-orm";
import {
  adClicks,
  adStatsDaily,
  aiActionAuditLogs,
  aiActionMemory,
  aiCostMonthly,
  aiConversationSummaries,
  aiMemoryEmbeddings,
  aiMemoryItems,
  aiPendingActions,
  aiSummaries,
  aiTokenLedgers,
  authChallenges,
  businessCategories,
  chatConversations,
  chatMessages,
  classificationLogs,
  expenseCategories,
  expenseDailyRollups,
  expenseDetails,
  expenses,
  financialGoals,
  inAppNotifications,
  localUsers,
  monthlyBehaviorSnapshots,
  monthlyReports,
  notificationLogs,
  pendingClarifications,
  profileLearningEvents,
  proSubscriptions,
  pushSubscriptions,
  rawSmsEvents,
  referrals,
  sessions,
  supportTickets,
  userAnalytics,
  userBudgets,
  userBusinesses,
  userContacts,
  userCorrectionRules,
  userCredentials,
  userDictionaries,
  userProfiles,
  userWallets,
  users,
  voiceUsage,
  webhookTokens,
} from "../../db/schema";

export type PurgeUserType = "oauth" | "local";

const userScope = (table: { userId: unknown; userType: unknown }, userId: number, userType: PurgeUserType) =>
  and(eq(table.userId as never, userId), eq(table.userType as never, userType));

/**
 * Deletes every user-scoped record while the caller's transaction is active.
 * This deliberately owns the entire cascade so account deletion cannot drift
 * as different admin/self-delete entry points evolve.
 */
export async function purgeUserData(tx: any, userId: number, userType: PurgeUserType): Promise<void> {
  const [conversationRows, businessRows] = await Promise.all([
    tx
      .select({ id: chatConversations.id })
      .from(chatConversations)
      .where(userScope(chatConversations, userId, userType)),
    tx
      .select({ id: userBusinesses.id })
      .from(userBusinesses)
      .where(userScope(userBusinesses, userId, userType)),
  ]);
  const conversationIds = conversationRows.map((row: { id: number }) => row.id);
  const businessIds = businessRows.map((row: { id: number }) => row.id);

  if (conversationIds.length) {
    await tx.delete(chatMessages).where(inArray(chatMessages.conversationId, conversationIds));
  }
  await tx.delete(aiConversationSummaries).where(userScope(aiConversationSummaries, userId, userType));
  await tx.delete(chatConversations).where(userScope(chatConversations, userId, userType));

  await tx.delete(aiMemoryEmbeddings).where(userScope(aiMemoryEmbeddings, userId, userType));
  await tx.delete(aiMemoryItems).where(userScope(aiMemoryItems, userId, userType));
  await tx.delete(aiActionAuditLogs).where(userScope(aiActionAuditLogs, userId, userType));
  await tx.delete(aiPendingActions).where(userScope(aiPendingActions, userId, userType));
  await tx.delete(aiActionMemory).where(userScope(aiActionMemory, userId, userType));
  await tx.delete(pendingClarifications).where(userScope(pendingClarifications, userId, userType));

  const userExpenses = await tx
    .select({ id: expenses.id })
    .from(expenses)
    .where(userScope(expenses, userId, userType));
  const expenseIds = userExpenses.map((row: { id: number }) => row.id);
  if (expenseIds.length) {
    await tx.delete(expenseDetails).where(inArray(expenseDetails.expenseId, expenseIds));
  }
  await tx.delete(expenses).where(userScope(expenses, userId, userType));
  await tx.delete(expenseDailyRollups).where(userScope(expenseDailyRollups, userId, userType));
  await tx.delete(aiCostMonthly).where(userScope(aiCostMonthly, userId, userType));
  await tx.delete(aiTokenLedgers).where(userScope(aiTokenLedgers, userId, userType));
  await tx.delete(userCorrectionRules).where(userScope(userCorrectionRules, userId, userType));
  await tx.delete(expenseCategories).where(userScope(expenseCategories, userId, userType));
  await tx.delete(userBudgets).where(userScope(userBudgets, userId, userType));
  await tx.delete(financialGoals).where(userScope(financialGoals, userId, userType));
  await tx.delete(monthlyReports).where(userScope(monthlyReports, userId, userType));
  await tx.delete(userWallets).where(userScope(userWallets, userId, userType));

  if (businessIds.length) {
    await tx.delete(businessCategories).where(inArray(businessCategories.businessId, businessIds));
  }
  await tx.delete(userContacts).where(userScope(userContacts, userId, userType));
  await tx.delete(userBusinesses).where(userScope(userBusinesses, userId, userType));

  await tx.delete(sessions).where(userScope(sessions, userId, userType));
  await tx.delete(userCredentials).where(userScope(userCredentials, userId, userType));
  await tx.delete(authChallenges).where(userScope(authChallenges, userId, userType));
  await tx.delete(webhookTokens).where(userScope(webhookTokens, userId, userType));
  await tx.delete(pushSubscriptions).where(userScope(pushSubscriptions, userId, userType));

  await tx.delete(userProfiles).where(userScope(userProfiles, userId, userType));
  await tx.delete(userAnalytics).where(userScope(userAnalytics, userId, userType));
  await tx.delete(supportTickets).where(userScope(supportTickets, userId, userType));
  await tx.delete(proSubscriptions).where(userScope(proSubscriptions, userId, userType));
  await tx.delete(aiSummaries).where(userScope(aiSummaries, userId, userType));
  await tx.delete(profileLearningEvents).where(userScope(profileLearningEvents, userId, userType));
  await tx.delete(monthlyBehaviorSnapshots).where(userScope(monthlyBehaviorSnapshots, userId, userType));
  await tx.delete(userDictionaries).where(userScope(userDictionaries, userId, userType));
  await tx.delete(classificationLogs).where(userScope(classificationLogs, userId, userType));
  await tx.delete(voiceUsage).where(userScope(voiceUsage, userId, userType));
  await tx.delete(rawSmsEvents).where(userScope(rawSmsEvents, userId, userType));
  await tx.delete(adClicks).where(userScope(adClicks, userId, userType));
  await tx.delete(inAppNotifications).where(userScope(inAppNotifications, userId, userType));
  await tx.delete(notificationLogs).where(userScope(notificationLogs, userId, userType));
  await tx.delete(referrals).where(
    or(
      and(eq(referrals.referrerId, userId), eq(referrals.referrerType, userType)),
      and(eq(referrals.referredId, userId), eq(referrals.referredType, userType)),
    ),
  );

  const identityTable = userType === "oauth" ? users : localUsers;
  await tx.delete(identityTable).where(eq(identityTable.id, userId));
}

/**
 * SMS Ingestion Router — SmartSpend
 * Receives financial SMS from iOS Shortcuts (or any automation tool),
 * parses them via AI, and saves them as Transactions.
 *
 * Endpoints:
 *   POST /api/sms/ingest  — Main ingestion endpoint (uses Webhook Token auth)
 *   POST /api/sms/token/generate — Generate a new webhook token (requires user session)
 *   GET  /api/sms/token   — Get current token (requires user session)
 *   GET  /api/sms/logs    — Get SMS processing logs (requires user session)
 */
import { Hono } from "hono";
import { getDb } from "./queries/connection";
import {
  webhookTokens,
  rawSmsEvents,
  expenses,
  users,
  localUsers,
} from "../db/schema";
import { eq, and, desc, gte } from "drizzle-orm";
import {
  parseSmsFinancialData,
  mapSmsToExpenseCategory,
  type SmsParseResult,
} from "./lib/sms-ai-parser";
import { parseSmsByRules } from "./lib/sms-rule-parser";
import { randomBytes } from "crypto";
import { env } from "./lib/env";
import { validateActiveSessionToken } from "./lib/session-validation";
import { getCookie } from "hono/cookie";
import { bumpFinanceCacheGen } from "./services/finance-semantic-layer";

export const smsApp = new Hono();

// ─── Rate limit: simple in-memory per-token tracker ───
const rateLimitMap = new Map<string, { count: number; resetAt: number }>();
const RATE_LIMIT = 30; // max 30 SMS per hour per token

// Auto-cleanup expired rate limiter entries every 5 minutes to prevent memory leak
setInterval(
  () => {
    const now = Date.now();
    for (const [token, entry] of rateLimitMap) {
      if (entry.resetAt < now) {
        rateLimitMap.delete(token);
      }
    }
  },
  5 * 60 * 1000,
);

function checkRateLimit(token: string): boolean {
  const now = Date.now();
  const entry = rateLimitMap.get(token);
  if (!entry || entry.resetAt < now) {
    rateLimitMap.set(token, { count: 1, resetAt: now + 60 * 60 * 1000 });
    return true;
  }
  if (entry.count >= RATE_LIMIT) return false;
  entry.count++;
  return true;
}

// ─── Magic Code Store (for zero-config iOS Shortcut setup) ───
const magicCodes = new Map<
  string,
  {
    webhookToken: string;
    userId: number;
    userType: string;
    expiresAt: number;
  }
>();

// Auto-cleanup expired codes every 2 minutes
setInterval(
  () => {
    const now = Date.now();
    for (const [code, entry] of magicCodes) {
      if (entry.expiresAt < now) magicCodes.delete(code);
    }
  },
  2 * 60 * 1000,
);

/** Generate a short, human-friendly 6-char code (no confusing chars like 0/O, 1/I/L) */
function generateShortCode(): string {
  const chars = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
  let code = "";
  const bytes = randomBytes(6);
  for (let i = 0; i < 6; i++) {
    code += chars[bytes[i] % chars.length];
  }
  return code;
}

/** Store a magic code tied to a user's webhook token. Returns the 6-char code. */
export function storeMagicCode(
  webhookToken: string,
  userId: number,
  userType: string,
): string {
  // Revoke any existing codes for this user first
  for (const [code, entry] of magicCodes) {
    if (entry.userId === userId && entry.userType === userType) {
      magicCodes.delete(code);
    }
  }
  const code = generateShortCode();
  magicCodes.set(code, {
    webhookToken,
    userId,
    userType,
    expiresAt: Date.now() + 5 * 60 * 1000, // 5 minutes
  });
  return code;
}

/** Exchange a magic code for the real webhook token. One-time use. */
function exchangeMagicCode(code: string): { token: string } | null {
  const normalized = code.toUpperCase().trim();
  const entry = magicCodes.get(normalized);
  if (!entry) return null;
  if (entry.expiresAt < Date.now()) {
    magicCodes.delete(normalized);
    return null;
  }
  // One-time use: delete after successful exchange
  magicCodes.delete(normalized);
  return { token: entry.webhookToken };
}

// ─── Helper: resolve user from session JWT (for protected endpoints) ───
async function getUserFromSession(c: any): Promise<{
  id: number;
  type: "local" | "oauth";
} | null> {
  // 1. Try Google OAuth cookie first
  const googleToken = getCookie(c, "google_session");
  if (googleToken) {
    const activeSession = await validateActiveSessionToken(googleToken, "oauth");
    if (activeSession) return { id: activeSession.userId, type: activeSession.userType };
  }

  // 2. Try Bearer token in Authorization header
  const authHeader = c.req.header("Authorization");
  if (authHeader?.startsWith("Bearer ")) {
    const token = authHeader.slice(7).trim();
    if (token) {
      const activeSession = await validateActiveSessionToken(token);
      if (activeSession) return { id: activeSession.userId, type: activeSession.userType };
    }
  }
  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /api/sms/ingest
// Called by iOS Shortcut. Authenticates via Bearer token in Authorization header
// or via ?token=... query parameter.
// ─────────────────────────────────────────────────────────────────────────────
smsApp.post("/ingest", async (c) => {
  const db = getDb();
  let token = "";

  const authHeader = c.req.header("Authorization");
  if (authHeader?.startsWith("Bearer ")) {
    token = authHeader.slice(7).trim();
  } else {
    token = c.req.query("token")?.trim() || "";
  }

  if (!token) {
    return c.json({ error: "Missing webhook token (Header or Query)" }, 401);
  }

  // Validate token against DB
  const [tokenRecord] = await db
    .select()
    .from(webhookTokens)
    .where(eq(webhookTokens.token, token))
    .limit(1);

  if (!tokenRecord) {
    return c.json({ error: "Invalid webhook token" }, 403);
  }

  // Rate limit check
  if (!checkRateLimit(token)) {
    return c.json({ error: "Rate limit exceeded. Max 30 SMS per hour." }, 429);
  }

  // Parse request body
  let body: {
    message?: string;
    sender?: string;
    timestamp?: string;
  };
  try {
    body = await c.req.json();
  } catch {
    return c.json({ error: "Invalid JSON body" }, 400);
  }

  const { message, sender, timestamp } = body;

  if (!message || typeof message !== "string" || message.trim().length < 5) {
    return c.json({ error: "Missing or too short 'message' field" }, 400);
  }

  const userId = tokenRecord.userId;
  const userType = tokenRecord.userType as "local" | "oauth";

  // ── Plan-based limits ──
  const userTable = userType === "oauth" ? users : localUsers;
  const [userRecord] = await db
    .select()
    .from(userTable)
    .where(eq(userTable.id, userId as any))
    .limit(1);
  const userPlan = (userRecord as any)?.plan || "free";

  // Get configurable limit from system_settings (admin dashboard), default: free=5, pro/ultra=unlimited
  let smsMonthlyLimit = userPlan === "free" ? 5 : 999999;
  try {
    const { getSystemSettings } = await import("./lib/settings-cache");
    const settings = await getSystemSettings();
    const val = settings[`sms_limit_${userPlan}`];
    if (val)
      smsMonthlyLimit = parseInt(val) || smsMonthlyLimit;
  } catch {
    /* use default */
  }

  // Count processed SMS this month
  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const { sql: sqlFn } = await import("drizzle-orm");
  const [countResult] = await db
    .select({ count: sqlFn`COUNT(*)` })
    .from(rawSmsEvents)
    .where(
      and(
        eq(rawSmsEvents.userId, userId),
        eq(rawSmsEvents.userType, userType),
        eq(rawSmsEvents.status, "processed"),
        gte(rawSmsEvents.createdAt, monthStart),
      ),
    );
  const usedThisMonth = Number((countResult as any)?.count || 0);

  if (usedThisMonth >= smsMonthlyLimit) {
    return c.json(
      {
        error: `الحد الشهري للرسائل (${smsMonthlyLimit}) انتهى. قم بترقية خطتك لزيادة الحد.`,
        limit: smsMonthlyLimit,
        used: usedThisMonth,
        plan: userPlan,
      },
      403,
    );
  }

  // Prevent duplicate SMS submissions (same user, exact message within last 24h)
  const duplicateCheck = await db
    .select({ id: rawSmsEvents.id })
    .from(rawSmsEvents)
    .where(
      and(
        eq(rawSmsEvents.userId, userId),
        eq(rawSmsEvents.userType, userType),
        eq(rawSmsEvents.message, message.trim()),
        gte(rawSmsEvents.createdAt, new Date(Date.now() - 24 * 60 * 60 * 1000)),
      ),
    )
    .limit(1);

  if (duplicateCheck.length > 0) {
    return c.json(
      {
        error: "Duplicate SMS: this message was already received recently.",
        duplicate: true,
      },
      409,
    );
  }

  // ── Step 1: Save Raw SMS Event (Audit Log) ──
  let smsId: number | null = null;
  try {
    const [inserted] = await db.insert(rawSmsEvents).values({
      userId,
      userType,
      message: message.trim(),
      sender: sender?.trim() || null,
      smsTimestamp: timestamp?.trim() || null,
      status: "pending",
    });
    smsId = (inserted as any)?.insertId || null;
  } catch (err) {
    console.error("[SMS Ingest] Failed to record raw SMS event:", err);
  }

  // ── Step 2: Run Rule-Based Parser (Fast Path) ──
  const ruleResult = parseSmsByRules(message);

  // ── Step 3: Hybrid Engine Selection (Rules vs AI) ──
  let parseResult: SmsParseResult | null = null;
  let parsedBy: "rules" | "ai" | "rules_fallback" = "rules";

  // Fast path: high-confidence rule match (>= 0.85) bypasses AI call
  if (ruleResult.transaction_detected && ruleResult.confidence >= 0.85 && ruleResult.amount) {
    parseResult = {
      transaction_detected: true,
      amount: ruleResult.amount,
      currency: ruleResult.currency || "EGP",
      direction: ruleResult.direction,
      provider: (ruleResult.provider as any) || "Unknown",
      category: (ruleResult.category as any) || "unknown",
      fee: ruleResult.fee,
      merchant: ruleResult.merchant,
      balance_after: ruleResult.balance_after,
      confidence: ruleResult.confidence,
      raw_extracted: { rule_result: ruleResult },
    };
    parsedBy = "rules";
  } else {
    // Fall back to Gemini AI parser with tenant-isolated user context
    const aiResult = await parseSmsFinancialData(message, { userId, userType });
    if (aiResult && aiResult.transaction_detected && aiResult.confidence >= 0.6 && aiResult.amount) {
      parseResult = aiResult;
      parsedBy = "ai";
    } else if (ruleResult.transaction_detected && ruleResult.amount) {
      // Secondary fallback to rule result if AI was inconclusive or returned null
      parseResult = {
        transaction_detected: true,
        amount: ruleResult.amount,
        currency: ruleResult.currency || "EGP",
        direction: ruleResult.direction,
        provider: (ruleResult.provider as any) || "Unknown",
        category: (ruleResult.category as any) || "unknown",
        fee: ruleResult.fee,
        merchant: ruleResult.merchant,
        balance_after: ruleResult.balance_after,
        confidence: ruleResult.confidence,
        raw_extracted: { rule_result: ruleResult, ai_result: aiResult },
      };
      parsedBy = "rules_fallback";
    } else {
      parseResult = aiResult || {
        transaction_detected: false,
        amount: null,
        currency: "EGP",
        direction: null,
        provider: "Unknown",
        category: "unknown",
        fee: null,
        merchant: null,
        balance_after: null,
        confidence: 0,
        raw_extracted: {},
      };
    }
  }

  // If no financial transaction detected or invalid amount/low confidence -> ignore and return
  if (!parseResult.transaction_detected || !parseResult.amount || parseResult.confidence < 0.5) {
    if (smsId) {
      await db
        .update(rawSmsEvents)
        .set({
          status: "ignored",
          metadata: {
            reason: !parseResult.transaction_detected
              ? "not_financial"
              : "low_confidence",
            confidence: parseResult.confidence,
            parsed_by: parsedBy,
            rule_result: {
              transaction_detected: ruleResult.transaction_detected,
              amount: ruleResult.amount,
              direction: ruleResult.direction,
              confidence: ruleResult.confidence,
              matched_rule: ruleResult.matched_rule,
              provider: ruleResult.provider,
            },
          },
        })
        .where(eq(rawSmsEvents.id, smsId));
    }
    return c.json(
      {
        success: true,
        transaction_detected: false,
        reason: !parseResult.transaction_detected
          ? "not_financial"
          : "low_confidence",
        confidence: parseResult.confidence,
        rule_result: {
          transaction_detected: ruleResult.transaction_detected,
          amount: ruleResult.amount,
          direction: ruleResult.direction,
          confidence: ruleResult.confidence,
          matched_rule: ruleResult.matched_rule,
          provider: ruleResult.provider,
        },
      },
      200,
    );
  }

  // ── Step 4: Save as Transaction ──
  const { category, subCategory, type } = mapSmsToExpenseCategory(parseResult);

  const descriptionParts = [
    parseResult.provider !== "Unknown" ? parseResult.provider : null,
    parseResult.merchant || null,
    sender ? `من: ${sender}` : null,
  ].filter(Boolean);

  const description = descriptionParts.join(" — ") || "SMS تلقائي";

  let transactionDate = timestamp ? new Date(timestamp) : new Date();
  if (isNaN(transactionDate.getTime())) {
    transactionDate = new Date();
  }

  await db.transaction(async (tx) => {
    const metadataObj = {
      sms_id: smsId,
      provider: parseResult!.provider,
      direction: parseResult!.direction,
      sms_category: parseResult!.category,
      confidence: parseResult!.confidence,
      fee: parseResult!.fee,
      balance_after: parseResult!.balance_after,
      parsed_by: parsedBy,
    };

    const [insertResult] = await tx.insert(expenses).values({
      userId,
      userType,
      type,
      amount: parseResult!.amount!.toString(),
      category,
      subCategory,
      description,
      rawText: message.trim(),
      source: "sms",
      date: transactionDate,
      parsedMetadata: metadataObj,
    });

    const {
      applyExpenseRollupDelta,
      expenseToRollupDelta,
      syncExpenseDetails,
    } = await import("./services/expense-rollups");

    if (insertResult?.insertId) {
      await syncExpenseDetails(tx, insertResult.insertId, message.trim(), metadataObj);
    }

    const delta = expenseToRollupDelta(
      {
        userId,
        userType,
        date: transactionDate,
        type,
        amount: parseResult!.amount!,
        source: "sms",
      },
      1,
    );
    await applyExpenseRollupDelta(tx, delta);

    // ── Step 5: Update SMS status ──
    if (smsId) {
      await tx
        .update(rawSmsEvents)
        .set({
          status: "processed",
          metadata: {
            transaction_saved: true,
            amount: parseResult!.amount,
            category,
            type,
            confidence: parseResult!.confidence,
            parsed_by: parsedBy,
          },
        })
        .where(
          and(
            eq(rawSmsEvents.id, smsId),
            eq(rawSmsEvents.userId, userId),
            eq(rawSmsEvents.userType, userType),
          ),
        );
    }
  });

  await bumpFinanceCacheGen(userId, userType);

  console.log(
    `✅ [SMS Ingest] User ${userId} | ${type} | ${parseResult.amount} EGP | ${category} | ${parseResult.provider}`,
  );

  return c.json(
    {
      success: true,
      transaction_detected: true,
      saved: true,
      amount: parseResult.amount,
      currency: parseResult.currency,
      direction: parseResult.direction,
      provider: parseResult.provider,
      category,
      subCategory,
      type,
      confidence: parseResult.confidence,
    },
    200,
  );
});

// ─────────────────────────────────────────────────────────────────────────────
// POST /api/sms/token/generate
// Generates a new webhook token for the authenticated user.
// Requires standard JWT session (same as other tRPC endpoints).
// ─────────────────────────────────────────────────────────────────────────────
smsApp.post("/token/generate", async (c) => {
  const db = getDb();
  const user = await getUserFromSession(c);

  if (!user) {
    return c.json({ error: "Unauthorized" }, 401);
  }

  // Delete old token if any
  await db
    .delete(webhookTokens)
    .where(
      and(
        eq(webhookTokens.userId, user.id as number),
        eq(webhookTokens.userType, user.type),
      ),
    );

  // Generate new secure token
  const newToken = `sms_${randomBytes(32).toString("hex")}`;

  await db.insert(webhookTokens).values({
    userId: user.id as number,
    userType: user.type,
    token: newToken,
    name: "iOS Shortcut Token",
  });

  return c.json({ success: true, token: newToken }, 200);
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/sms/token
// Returns the current webhook token for the authenticated user.
// ─────────────────────────────────────────────────────────────────────────────
smsApp.get("/token", async (c) => {
  const db = getDb();
  const user = await getUserFromSession(c);

  if (!user) {
    return c.json({ error: "Unauthorized" }, 401);
  }

  const [record] = await db
    .select()
    .from(webhookTokens)
    .where(
      and(
        eq(webhookTokens.userId, user.id as number),
        eq(webhookTokens.userType, user.type),
      ),
    )
    .limit(1);

  if (!record) {
    return c.json({ token: null, hasToken: false }, 200);
  }

  return c.json(
    { token: record.token, hasToken: true, createdAt: record.createdAt },
    200,
  );
});

// ─────────────────────────────────────────────────────────────────────────────
// POST /api/sms/exchange
// Public endpoint — iOS Shortcut sends its magic code here to get the real
// webhook token + ingest URL. No session auth required.
// ─────────────────────────────────────────────────────────────────────────────
smsApp.post("/exchange", async (c) => {
  let body: { code?: string };
  try {
    body = await c.req.json();
  } catch {
    return c.json({ error: "Invalid JSON body" }, 400);
  }

  const code = body?.code?.toString().trim();
  if (!code) {
    return c.json({ error: "Missing 'code' field" }, 400);
  }

  const result = exchangeMagicCode(code);
  if (!result) {
    return c.json(
      {
        error: "Invalid or expired code. Generate a new one from the website.",
      },
      401,
    );
  }

  // Build the ingest URL from the request origin (works with any tunnel)
  const origin = new URL(c.req.url).origin;
  return c.json({
    success: true,
    token: result.token,
    ingestUrl: `${origin}/api/sms/ingest`,
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/sms/shortcut-download?code=XXXXXX
// Public endpoint — generates a personalized .shortcut file with the user's
// token embedded. Uses magic code for auth so no session header is needed.
// ─────────────────────────────────────────────────────────────────────────────
smsApp.get("/shortcut-download", async (c) => {
  const code = c.req.query("code")?.trim();
  if (!code) {
    return c.json({ error: "Missing 'code' parameter" }, 400);
  }

  const result = exchangeMagicCode(code);
  if (!result) {
    return c.json(
      {
        error:
          "Invalid or expired code. Go back to SmartSpend and click Connect iPhone again.",
      },
      401,
    );
  }

  // Build ingest URL from the request origin (works with any tunnel)
  const origin = new URL(c.req.url).origin;
  const ingestUrl = `${origin}/api/sms/ingest`;

  const { generateShortcutFile } = await import("./lib/shortcut-generator");
  const fileBuffer = generateShortcutFile(result.token, ingestUrl);

  return new Response(new Uint8Array(fileBuffer), {
    headers: {
      "Content-Type": "application/x-apple-shortcut",
      "Content-Disposition": 'attachment; filename="SmartSpend SMS.shortcut"',
      "Cache-Control": "no-store",
    },
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/sms/logs
// Returns last 50 SMS processing logs for the authenticated user.
// ─────────────────────────────────────────────────────────────────────────────
smsApp.get("/logs", async (c) => {
  const db = getDb();
  const user = await getUserFromSession(c);

  if (!user) {
    return c.json({ error: "Unauthorized" }, 401);
  }

  const logs = await db
    .select()
    .from(rawSmsEvents)
    .where(
      and(
        eq(rawSmsEvents.userId, user.id as number),
        eq(rawSmsEvents.userType, user.type),
      ),
    )
    .orderBy(desc(rawSmsEvents.createdAt))
    .limit(50);

  return c.json({ logs }, 200);
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/sms/android-connect
// Called from the web when user taps "Connect Android".
// Generates/fetches token, then returns a deep-link URL the browser opens.
// The deep link opens SmartSpend Sync APK with token pre-filled (no copy/paste).
// ─────────────────────────────────────────────────────────────────────────────
smsApp.get("/android-connect", async (c) => {
  const db = getDb();
  const user = await getUserFromSession(c);

  if (!user) {
    return c.json({ error: "Unauthorized" }, 401);
  }

  // Fetch existing token or create one
  let [record] = await db
    .select()
    .from(webhookTokens)
    .where(
      and(
        eq(webhookTokens.userId, user.id as number),
        eq(webhookTokens.userType, user.type),
      ),
    )
    .limit(1);

  if (!record) {
    const newToken = `sms_${randomBytes(32).toString("hex")}`;
    await db.insert(webhookTokens).values({
      userId: user.id as number,
      userType: user.type,
      token: newToken,
      name: "Android Sync Token",
    });
    [record] = await db
      .select()
      .from(webhookTokens)
      .where(
        and(
          eq(webhookTokens.userId, user.id as number),
          eq(webhookTokens.userType, user.type),
        ),
      )
      .limit(1);
  }

  const origin = new URL(c.req.url).origin;
  const ingestUrl = `${origin}/api/sms/ingest`;

  // Deep link format: smartspend://connect?token=TOKEN&url=INGEST_URL
  const deepLink = `smartspend://connect?token=${encodeURIComponent(record.token)}&url=${encodeURIComponent(ingestUrl)}`;

  return c.json({
    success: true,
    deepLink,
    token: record.token,
    ingestUrl,
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// POST /api/sms/android-status
// Called by the Android APK on startup to confirm it's alive.
// Authenticated via Bearer token (same webhook token).
// ─────────────────────────────────────────────────────────────────────────────
smsApp.post("/android-status", async (c) => {
  const db = getDb();
  let token = "";
  const authHeader = c.req.header("Authorization");
  if (authHeader?.startsWith("Bearer ")) token = authHeader.slice(7).trim();
  else token = c.req.query("token")?.trim() || "";

  if (!token) return c.json({ error: "Missing token" }, 401);

  const [tokenRecord] = await db
    .select()
    .from(webhookTokens)
    .where(eq(webhookTokens.token, token))
    .limit(1);

  if (!tokenRecord) return c.json({ error: "Invalid token" }, 403);

  let body: {
    appVersion?: string;
    androidVersion?: string;
    deviceModel?: string;
  } = {};
  try {
    body = await c.req.json();
  } catch {
    /* optional body */
  }

  console.log(
    `[Android Status] User ${tokenRecord.userId} | App v${body.appVersion || "?"} | Android ${body.androidVersion || "?"} | ${body.deviceModel || "?"}`,
  );

  return c.json({
    success: true,
    status: "connected",
    message: "SmartSpend Sync is active ✅",
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/sms/metrics
// Returns transaction parsing statistics, success rates, and provider metrics
// ─────────────────────────────────────────────────────────────────────────────
smsApp.get("/metrics", async (c) => {
  const db = getDb();
  const user = await getUserFromSession(c);

  if (!user) {
    return c.json({ error: "Unauthorized" }, 401);
  }

  const events = await db
    .select()
    .from(rawSmsEvents)
    .where(
      and(
        eq(rawSmsEvents.userId, user.id as number),
        eq(rawSmsEvents.userType, user.type),
      ),
    )
    .orderBy(desc(rawSmsEvents.createdAt))
    .limit(1000);

  const total = events.length;
  let processed = 0;
  let ignored = 0;
  let error = 0;

  let rulesCount = 0;
  let aiCount = 0;
  let fallbackCount = 0;

  const providerStats: Record<string, { total: number; failed: number }> = {};

  for (const e of events) {
    if (e.status === "processed") processed++;
    else if (e.status === "ignored") ignored++;
    else if (e.status === "error") error++;

    const meta = e.metadata as any;
    const parsedBy = meta?.parsed_by || "unknown";
    if (parsedBy === "rules") rulesCount++;
    else if (parsedBy === "ai") aiCount++;
    else if (parsedBy === "rules_fallback") fallbackCount++;

    const provider = meta?.provider || meta?.rule_result?.provider || "Unknown";
    if (!providerStats[provider]) {
      providerStats[provider] = { total: 0, failed: 0 };
    }
    providerStats[provider].total++;
    if (e.status === "ignored" && meta?.reason === "low_confidence") {
      providerStats[provider].failed++;
    }
  }

  const failCount =
    error +
    events.filter((e) => (e.metadata as any)?.reason === "low_confidence")
      .length;
  const accuracyRate =
    processed + failCount > 0 ? processed / (processed + failCount) : 1.0;

  return c.json(
    {
      success: true,
      metrics: {
        totalReceived: total,
        statusBreakdown: { processed, ignored, error },
        parserBreakdown: {
          rules: rulesCount,
          ai: aiCount,
          fallback: fallbackCount,
        },
        accuracyRate: Math.round(accuracyRate * 100) / 100,
        providerBreakdown: providerStats,
      },
    },
    200,
  );
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/sms/unparsed
// Returns the 50 most recent failed/ignored bank transactions for review/audit
// ─────────────────────────────────────────────────────────────────────────────
smsApp.get("/unparsed", async (c) => {
  const db = getDb();
  const user = await getUserFromSession(c);

  if (!user) {
    return c.json({ error: "Unauthorized" }, 401);
  }

  const unparsedEvents = await db
    .select()
    .from(rawSmsEvents)
    .where(
      and(
        eq(rawSmsEvents.userId, user.id as number),
        eq(rawSmsEvents.userType, user.type),
        eq(rawSmsEvents.status, "ignored"),
      ),
    )
    .orderBy(desc(rawSmsEvents.createdAt))
    .limit(100);

  const filtered = unparsedEvents
    .filter((e) => {
      const meta = e.metadata as any;
      return (
        meta?.reason === "low_confidence" || meta?.reason === "AI returned null"
      );
    })
    .slice(0, 50);

  return c.json(
    {
      success: true,
      unparsed: filtered.map((e) => ({
        id: e.id,
        sender: e.sender,
        message: e.message,
        redactedMessage: e.message, // raw text since database is unredacted
        timestamp: e.smsTimestamp,
        reason: (e.metadata as any)?.reason,
        ruleResult: (e.metadata as any)?.rule_result,
        createdAt: e.createdAt,
      })),
    },
    200,
  );
});

